<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth;

use Nimbly\Capsule\Response;
use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Rest\IntrospectionController;
use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;

class IntrospectionTest extends OidcIntegrationTestCase
{
    private IntrospectionController $controller;
    private TokenSigner $signer;

    protected function setUp(): void
    {
        parent::setUp();
        $this->controller = $this->container->get(IntrospectionController::class);
        $this->signer = $this->container->get(TokenSigner::class);
    }

    private function issueAccessToken(string $sub = self::USER_ID, string $scope = 'openid profile'): string
    {
        return $this->signer->sign(self::TENANT, [
            'sub' => $sub,
            'azp' => self::CLIENT_ID,
            'iss' => 'http://localhost/oauth/openid/' . self::TENANT,
            'tenant' => self::TENANT,
            'scope' => $scope,
            'roles' => [],
            'groups' => [],
        ], new \DateInterval('PT10M'));
    }

    private function introspect(string $token, array $clientAuth = []): \Psr\Http\Message\ResponseInterface
    {
        $auth = $clientAuth !== [] ? $clientAuth : [
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
        ];
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/introspect', [
            'token' => $token,
            ...$auth,
        ]);
        return $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);
    }

    public function testValidTokenIsActive(): void
    {
        $token = $this->issueAccessToken();

        $response = $this->introspect($token);

        $this->assertSame(200, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertTrue($body['active']);
        $this->assertSame(self::USER_ID, $body['sub']);
        $this->assertSame(self::CLIENT_ID, $body['client_id']);
        $this->assertSame(self::TENANT, $body['tenant']);
    }

    public function testValidTokenContainsScopeAndIssuer(): void
    {
        $token = $this->issueAccessToken(scope: 'openid profile email');

        $response = $this->introspect($token);

        $body = $this->decodeJson($response);
        $this->assertTrue($body['active']);
        $this->assertStringContainsString('openid', $body['scope']);
        $this->assertStringContainsString('profile', $body['scope']);
        $this->assertArrayHasKey('iss', $body);
        $this->assertArrayHasKey('exp', $body);
    }

    public function testRevokedTokenIsInactive(): void
    {
        $token = $this->issueAccessToken();
        $payload = $this->signer->parseSignedPayload(self::TENANT, $token);
        $jti = $payload['jti'];

        $this->tokenRevocation->revokeJti($jti, self::TENANT, 'access_token', new \DateTimeImmutable('+10 minutes'));

        $response = $this->introspect($token);

        $body = $this->decodeJson($response);
        $this->assertFalse($body['active']);
    }

    public function testInvalidTokenIsInactive(): void
    {
        $response = $this->introspect('not-a-valid-jwt');

        $body = $this->decodeJson($response);
        $this->assertFalse($body['active']);
    }

    public function testMissingTokenReturns400(): void
    {
        $request = $this->makeRequest('POST', '/oauth/openid/tenant1/introspect', [
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => self::TENANT]);

        $this->assertSame(400, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_request', $body['error']);
    }

    public function testBadClientAuthReturns401(): void
    {
        $token = $this->issueAccessToken();

        $response = $this->introspect($token, [
            'client_id' => self::CLIENT_ID,
            'client_secret' => 'wrong-secret',
        ]);

        $this->assertSame(401, $response->getStatusCode());
        $body = $this->decodeJson($response);
        $this->assertSame('invalid_client', $body['error']);
    }

    public function testUnknownClientReturns401(): void
    {
        $token = $this->issueAccessToken();

        $response = $this->introspect($token, [
            'client_id' => 'no-such-client',
            'client_secret' => 'whatever',
        ]);

        $this->assertSame(401, $response->getStatusCode());
    }

    public function testTokenFromOtherTenantIsInactive(): void
    {
        $token = $this->issueAccessToken();

        $request = $this->makeRequest('POST', '/oauth/openid/other-tenant/introspect', [
            'token' => $token,
            'client_id' => self::CLIENT_ID,
            'client_secret' => self::CLIENT_SECRET,
        ]);

        $response = $this->controller->post($request, new Response(200), ['tenant' => 'other-tenant']);

        $body = $this->decodeJson($response);
        $this->assertFalse($body['active']);
    }
}
